parameters.jsCode:
// ===== SETTINGS =====
const BRAND = 'WorkWise';
const MODE_WEIGHTS = { unsplash: 3, ai: 3, article: 1, text: 3 };  // higher number = appears more often
const FORCE_MODE = '';   // testing only: 'unsplash' | 'ai' | 'article' | 'text'
const FORCE = '';        // testing only: 'gradient' | 'card' | 'spotlight' | 'list' | 'magazine' | 'takeaway' | 'breaking' | 'versus' | 'bold'

// post data always comes from here, so retries after a rejection still work
const d = $('Prepare Post Data').first().json;

// config node (works whether yours is named with or without the 1)
let cfg = {};
try { cfg = $('Config & Posting Slot1').first().json; }
catch (e) { try { cfg = $('Config & Posting Slot').first().json; } catch (e2) {} }

// layouts available for each mode
const HAS_BA = !!(d.before && d.after);
const PHOTO_LAYOUTS = ['gradient', 'card', 'spotlight', 'magazine', 'breaking', 'takeaway'];
const TEXT_LAYOUTS = ['list', 'takeaway', 'bold'].concat(HAS_BA ? ['versus'] : []);
const layoutsFor = m => (m === 'text' ? TEXT_LAYOUTS : PHOTO_LAYOUTS);

// layouts already rejected earlier in this same run
const used = [];
for (let r = 0; r < $runIndex; r++) {
  try { used.push($('Build Final Post').all(0, r)[0].json.template); } catch (e) {}
}
const left = m => layoutsFor(m).filter(t => !used.includes(t));

const pickWeighted = w => {
  let r = Math.random() * Object.values(w).reduce((a, b) => a + b, 0);
  for (const [k, v] of Object.entries(w)) { if ((r -= v) < 0) return k; }
  return Object.keys(w)[0];
};

// choose a mode that still has an unused layout
let allowed = {};
for (const [m, wt] of Object.entries(MODE_WEIGHTS)) { if (wt > 0 && left(m).length) allowed[m] = wt; }
if (!Object.keys(allowed).length) {
  for (const [m, wt] of Object.entries(MODE_WEIGHTS)) { if (wt > 0) allowed[m] = wt; }
}
const MODE = FORCE_MODE || pickWeighted(allowed);
const candidates = left(MODE).length ? left(MODE) : layoutsFor(MODE);
const name = FORCE || candidates[Math.floor(Math.random() * candidates.length)];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const points = String(d.pointsText || '').split('\n').map(s => s.trim()).filter(Boolean);
const H = esc(d.headline);
const T = esc(d.category || 'AI NEWS').toUpperCase();
const SRC = esc(d.source_name);
const S1 = esc(points[0] || '');
const S2 = esc(points.slice(0, 2).join(' '));
const TAKE = esc(d.takeaway || points[0] || '');
const BEF = esc(d.before || '');
const AFT = esc(d.after || '');
const fs = (s, big, mid, small) => { const n = String(s).length; return n <= 45 ? big : n <= 75 ? mid : small; };

// ===== PHOTO SOURCES =====
const fromUnsplash = async () => {
  const key = String(cfg.unsplashKey || '');
  if (!key || key.startsWith('PASTE')) return null;
  const r = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.unsplash.com/search/photos',
    qs: { query: d.image_query || d.headline, per_page: 8, content_filter: 'high' },
    headers: { Authorization: 'Client-ID ' + key, 'Accept-Version': 'v1' },
    json: true,
    timeout: 8000
  });
  const list = (r && r.results) || [];
  if (!list.length) return null;
  const p = list[Math.floor(Math.random() * Math.min(5, list.length))];
  // Unsplash API rule: ping the download endpoint when a photo is used
  try {
    await this.helpers.httpRequest({ method: 'GET', url: p.links.download_location, headers: { Authorization: 'Client-ID ' + key }, timeout: 5000 });
  } catch (e) {}
  const raw = p.urls.raw + (p.urls.raw.includes('?') ? '&' : '?') + 'w=1400&q=80&fit=max';
  return { url: raw, credit: 'Photo: ' + p.user.name + ' / Unsplash' };
};

const fromArticle = async () => {
  if (!d.story_url) return null;
  const page = String(await this.helpers.httpRequest({
    method: 'GET', url: d.story_url, timeout: 8000,
    headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36' }
  }));
  const m = page.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i)
         || page.match(/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["']/i);
  if (!m) return null;
  let u = m[1].replace(/&amp;/g, '&');
  if (u.startsWith('//')) u = 'https:' + u;
  return { url: u, credit: '' };
};

const fromAI = async () => ({
  url: 'https://image.pollinations.ai/prompt/' + encodeURIComponent(String(d.image_query || d.headline) + ', modern tech illustration, cinematic lighting') + '?width=1080&height=1080&nologo=true',
  credit: ''
});

const sources = { unsplash: fromUnsplash, article: fromArticle, ai: fromAI };
let photo = { url: '', credit: '' };
if (MODE !== 'text') {
  const order = [MODE, 'unsplash', 'ai'].filter((v, i, a) => a.indexOf(v) === i);  // chosen mode first, then fallbacks
  let got = null;
  for (const s of order) {
    try { got = await sources[s](); } catch (e) { got = null; }
    if (got && got.url) break;
  }
  photo = got || await fromAI();
}
const img = photo.url;
const HAS_PHOTO = MODE !== 'text';
const CREDIT = photo.credit
  ? `<div style="position:absolute;right:22px;bottom:18px;background:rgba(0,0,0,.5);color:#fff;font-size:17px;padding:4px 12px;border-radius:8px;font-family:Poppins,sans-serif">${esc(photo.credit)}</div>`
  : '';

const accents = ['#d9f24a', '#ff6b6b', '#ffd166', '#4cc9f0', '#b794f6', '#ff9f43'];
const accent = accents[Math.floor(Math.random() * accents.length)];
const fonts = '<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@500;600;700;800&family=Playfair+Display:wght@700&display=swap" rel="stylesheet">';

const templates = {
  // 1. photo fading into black (your iPhone 12 reference)
  gradient: `<div style="width:1080px;height:1350px;position:relative;background:#000;font-family:Poppins,sans-serif;color:#fff;overflow:hidden">
    <img src="${img}" style="position:absolute;top:0;left:0;width:1080px;height:860px;object-fit:cover">
    <div style="position:absolute;top:420px;left:0;width:1080px;height:930px;background:linear-gradient(to bottom,rgba(0,0,0,0),#000 55%)"></div>
    <div style="position:absolute;left:70px;right:70px;bottom:80px">
      <div style="font-size:32px;font-weight:600;letter-spacing:5px;color:${accent}">${T}</div>
      <div style="font-size:${fs(d.headline, 64, 56, 48)}px;font-weight:800;line-height:1.1;margin:14px 0 28px;text-transform:uppercase">${H}</div>
      <div style="height:2px;background:#555;margin-bottom:28px"></div>
      <div style="font-size:38px;line-height:1.4;color:#eee">${S1}</div>
    </div>${CREDIT}</div>`,

  // 2. white card on a colour frame (your Facebook reference)
  card: `<div style="width:1080px;height:1350px;position:relative;background:${accent};padding:60px;box-sizing:border-box;font-family:Poppins,sans-serif">
    <div style="background:#fff;border-radius:36px;height:1230px;padding:60px;box-sizing:border-box;overflow:hidden;display:flex;flex-direction:column">
      <div style="font-size:${fs(d.headline, 68, 58, 50)}px;font-weight:800;line-height:1.1;color:#111">${H}</div>
      <div style="font-size:30px;color:#555;margin:26px 0 34px">By <b>${BRAND}</b> · ${SRC}</div>
      <img src="${img}" style="width:100%;flex:1;min-height:0;object-fit:cover;border-radius:20px;display:block">
    </div>${CREDIT}</div>`,

  // 3. Betakit-style spotlight card (your Slate reference)
  spotlight: `<div style="width:1080px;height:1350px;position:relative;background:#0d0d0d;padding:90px 70px;box-sizing:border-box;font-family:Poppins,sans-serif;display:flex;flex-direction:column;justify-content:center">
    <div style="background:#fff;border-radius:24px;overflow:hidden">
      <div style="padding:26px;text-align:center;font-size:40px;font-weight:800;color:#111">${BRAND} <span style="font-size:22px;font-weight:600;color:#777">· ${T}</span></div>
      <div style="background:#000;color:#fff;padding:44px 50px">
        <div style="font-family:'Playfair Display',Georgia,serif;font-size:${fs(d.headline, 54, 48, 42)}px;font-weight:700;line-height:1.2">${H}</div>
        <div style="font-size:27px;font-weight:500;line-height:1.5;color:#ccc;margin-top:24px">${S2}</div>
      </div>
      <img src="${img}" style="width:100%;height:480px;object-fit:cover;display:block">
    </div>${CREDIT}</div>`,

  // 4. numbered list (your "9 tools" reference)
  list: `<div style="width:1080px;height:1350px;position:relative;background:#efeee6;padding:80px 70px;box-sizing:border-box;font-family:Poppins,sans-serif;color:#111;display:flex;flex-direction:column;justify-content:center">
    <div style="text-align:center;font-size:${fs(d.headline, 64, 54, 46)}px;font-weight:800;line-height:1.1">${H}</div>
    <div style="text-align:center;margin:26px 0 44px"><span style="background:${accent};padding:6px 24px;border-radius:10px;font-size:30px;font-weight:600">${T}</span></div>
    ${points.slice(0, 5).map((t, i) => `<div style="display:flex;align-items:center;margin-bottom:22px"><div style="width:64px;height:64px;border-radius:50%;background:#111;color:#fff;font-size:30px;font-weight:800;display:flex;align-items:center;justify-content:center;margin-right:24px;flex-shrink:0">${i + 1}</div><div style="font-size:34px;font-weight:600;line-height:1.3">${esc(t)}</div></div>`).join('')}
    <div style="text-align:center;margin-top:30px;font-size:26px;color:#777">${BRAND} · Source: ${SRC}</div>
  </div>`,

  // 5. NEW - full-bleed magazine cover
  magazine: `<div style="width:1080px;height:1350px;position:relative;overflow:hidden;background:#000;font-family:Poppins,sans-serif;color:#fff">
    <img src="${img}" style="position:absolute;top:0;left:0;width:1080px;height:1350px;object-fit:cover">
    <div style="position:absolute;top:0;left:0;width:1080px;height:1350px;background:linear-gradient(to bottom,rgba(0,0,0,.45) 0%,rgba(0,0,0,.05) 30%,rgba(0,0,0,.9) 100%)"></div>
    <div style="position:absolute;left:70px;top:70px;background:${accent};color:#111;font-weight:800;font-size:26px;padding:8px 22px;border-radius:999px;letter-spacing:3px">${T}</div>
    <div style="position:absolute;right:70px;top:74px;font-size:30px;font-weight:800;letter-spacing:2px">${BRAND}</div>
    <div style="position:absolute;left:70px;right:70px;bottom:100px">
      <div style="font-family:'Playfair Display',Georgia,serif;font-size:${fs(d.headline, 84, 72, 60)}px;font-weight:700;line-height:1.08">${H}</div>
      <div style="width:120px;height:8px;background:${accent};margin:34px 0"></div>
      <div style="font-size:36px;line-height:1.4;color:#e8e8e8">${S1}</div>
    </div>${CREDIT}</div>`,

  // 6. NEW - big "what this means for you" statement
  takeaway: `<div style="width:1080px;height:1350px;position:relative;background:${accent};padding:80px;box-sizing:border-box;font-family:Poppins,sans-serif;color:#111;display:flex;flex-direction:column">
    <div style="display:flex;justify-content:space-between;align-items:center;font-weight:800;font-size:30px;letter-spacing:3px"><span>${BRAND}</span><span style="background:#111;color:#fff;padding:8px 22px;border-radius:999px;font-size:24px">${T}</span></div>
    <div style="flex:1;display:flex;flex-direction:column;justify-content:center">
      <div style="font-size:28px;font-weight:700;letter-spacing:4px;margin-bottom:30px">WHAT THIS MEANS FOR YOU</div>
      <div style="font-size:${fs(d.takeaway || points[0] || '', 80, 68, 56)}px;font-weight:800;line-height:1.12">&ldquo;${TAKE}&rdquo;</div>
    </div>
    ${HAS_PHOTO
      ? `<div style="display:flex;align-items:center;gap:28px;background:#111;border-radius:28px;padding:22px;color:#fff">
          <img src="${img}" style="width:190px;height:190px;object-fit:cover;border-radius:18px;flex-shrink:0">
          <div><div style="font-size:30px;font-weight:600;line-height:1.3">${H}</div><div style="font-size:22px;opacity:.7;margin-top:8px">Source: ${SRC}</div></div>
        </div>`
      : `<div style="background:#111;border-radius:28px;padding:34px;color:#fff"><div style="font-size:34px;font-weight:700;line-height:1.3">${H}</div><div style="font-size:22px;opacity:.7;margin-top:10px">Source: ${SRC}</div></div>`}
    ${CREDIT}</div>`,

  // 7. NEW - news-flash style
  breaking: `<div style="width:1080px;height:1350px;position:relative;background:#fff;font-family:Poppins,sans-serif;color:#111;overflow:hidden">
    <img src="${img}" style="width:1080px;height:760px;object-fit:cover;display:block">
    <div style="position:absolute;top:50px;left:0;background:#e11d48;color:#fff;font-weight:800;font-size:40px;letter-spacing:4px;padding:14px 40px 14px 70px">JUST IN</div>
    <div style="position:absolute;top:60px;right:60px;color:#fff;font-weight:800;font-size:30px;text-shadow:0 2px 8px rgba(0,0,0,.6)">${BRAND}</div>
    <div style="padding:56px 70px">
      <div style="font-size:${fs(d.headline, 72, 62, 54)}px;font-weight:800;line-height:1.1">${H}</div>
      <div style="font-size:32px;line-height:1.45;color:#444;margin-top:28px">${S1}</div>
    </div>
    <div style="position:absolute;left:0;right:0;bottom:0;height:70px;background:#111;color:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 70px;font-size:24px;font-weight:600"><span>${BRAND}</span><span>Source: ${SRC}</span></div>
    ${CREDIT.replace('bottom:18px', 'bottom:90px')}</div>`,

  // 8. NEW - before / now comparison (your "2025 vs 2026" reference)
  versus: `<div style="width:1080px;height:1350px;position:relative;background:#0d0d0d;padding:80px 60px;box-sizing:border-box;font-family:Poppins,sans-serif;color:#fff;display:flex;flex-direction:column">
    <div style="text-align:center;font-size:26px;letter-spacing:5px;color:${accent};font-weight:700">${T}</div>
    <div style="text-align:center;font-size:${fs(d.headline, 66, 56, 48)}px;font-weight:800;line-height:1.1;margin:20px 0 50px">${H}</div>
    <div style="display:flex;gap:24px;flex:1">
      <div style="flex:1;background:#1c1c1c;border-radius:28px;padding:44px 36px;display:flex;flex-direction:column;justify-content:center">
        <div style="font-size:30px;font-weight:800;color:#888;letter-spacing:3px;margin-bottom:24px">BEFORE</div>
        <div style="font-size:42px;font-weight:600;line-height:1.3;color:#bbb">${BEF}</div>
      </div>
      <div style="flex:1;background:${accent};color:#111;border-radius:28px;padding:44px 36px;display:flex;flex-direction:column;justify-content:center">
        <div style="font-size:30px;font-weight:800;letter-spacing:3px;margin-bottom:24px">NOW</div>
        <div style="font-size:42px;font-weight:700;line-height:1.3">${AFT}</div>
      </div>
    </div>
    <div style="text-align:center;margin-top:36px;font-size:24px;color:#888">${BRAND} · Source: ${SRC}</div>
  </div>`,

  // 9. NEW - text-only bold statement
  bold: `<div style="width:1080px;height:1350px;position:relative;background:#111;padding:90px 80px;box-sizing:border-box;font-family:Poppins,sans-serif;color:#fff;display:flex;flex-direction:column;justify-content:center">
    <div style="font-size:28px;font-weight:700;letter-spacing:5px;color:${accent};margin-bottom:30px">${T} · ${BRAND}</div>
    <div style="font-size:${fs(d.headline, 92, 78, 64)}px;font-weight:800;line-height:1.05">${H}</div>
    <div style="width:160px;height:10px;background:${accent};margin:44px 0"></div>
    <div style="font-size:38px;line-height:1.45;color:#ddd">${S1}</div>
    <div style="margin-top:60px;font-size:24px;color:#888">Source: ${SRC}</div>
  </div>`
};

return { json: { html: fonts + templates[name], css: '', template: name, mode: MODE, photoCredit: photo.credit } };

// links of every story rejected so far in this execution
const rejected = [];
for (let r = 0; r <= $runIndex; r++) {
  try { rejected.push($('Prepare Post Data').all(0, r)[0].json.story_url); } catch (e) {}
}

// take the full sorted list, drop rejected stories, keep 15
const stories = $('Newest First').all().filter(i => !rejected.includes(i.json.link));
return stories.slice(0, 15);
